package com.fixmer.genesis.technology.workspace.live122;
import com.fixmer.genesis.technology.workspace.collaboration121.*;import com.fixmer.genesis.technology.server.firstlaunch.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.*;import static com.fixmer.genesis.technology.workspace.collaboration121.WorkspacePolicy121.*;
/** Single serialized IO owner. Actor and display name MUST be supplied by current server context. */
public final class WorkspaceHub122 implements AutoCloseable {
 private final Path root;private final byte[] key;private final Map<UUID,Room> rooms=new HashMap<>();private boolean closed;
 private static final Map<String,Set<String>> FIELDS=Map.ofEntries(Map.entry("IMPORT",Set.of()),Map.entry("LIST",Set.of()),Map.entry("CREATE",Set.of("text")),Map.entry("VIEW",Set.of()),Map.entry("SYNC",Set.of("path")),Map.entry("OPEN",Set.of("path")),Map.entry("LEASE",Set.of("path")),Map.entry("POLL",Set.of("path","anchor","selection","color","sequence","session")),Map.entry("EDIT",Set.of("path","batch","lease")),Map.entry("NEW",Set.of("path","rev")),Map.entry("MEMBER",Set.of("target","role","prefix","deny","hidden","rev")),Map.entry("PREVIEW",Set.of("paths","rev")),Map.entry("APPROVE",Set.of("hash","rev")),Map.entry("DELETE_REVIEW",Set.of("path","rev")),Map.entry("DELETE",Set.of("path","ticket","rev")),Map.entry("RENAME",Set.of("path","target","rev")),Map.entry("RESTORE",Set.of("path","history","rev")),Map.entry("HISTORY",Set.of("path")),Map.entry("EXPORT",Set.of()),Map.entry("LEAVE",Set.of()));
 private static final class Room {final UUID id,owner;final String title;final WorkspaceEngine121 engine;final WorkspacePresence121 presence=new WorkspacePresence121(()->System.nanoTime()/1_000_000,5000);final Map<UUID,UUID> sessions=new HashMap<>();final Map<String,WorkspaceRelease121.Snapshot> previews=new LinkedHashMap<>();Room(UUID id,UUID owner,String title,WorkspaceEngine121 engine){this.id=id;this.owner=owner;this.title=title;this.engine=engine;}}
 public WorkspaceHub122(Path root)throws IOException{this.root=FirstLaunchFiles.safe(root);Files.createDirectories(this.root);FirstLaunchFiles.privateMode(this.root);Path secret=this.root.resolve("leases122.key");if(!Files.exists(secret)){byte[] k=new byte[32];new SecureRandom().nextBytes(k);FirstLaunchFiles.write(secret,k,false);}key=FirstLaunchFiles.read(secret,32);if(key.length!=32)throw new IOException("KEY");}
 private static UUID uuid(String s){UUID u=UUID.fromString(s);if(!u.toString().equals(s)||u.equals(new UUID(0,0)))throw new IllegalArgumentException("UUID");return u;}
 private static long num(String s){if(s==null||!s.matches("0|[1-9][0-9]{0,18}"))throw new IllegalArgumentException("NUMBER");return Long.parseLong(s);}
 public static void request(Map<String,String> q){uuid(q.get("request"));var expected=FIELDS.get(q.get("op"));if(expected==null)throw new IllegalArgumentException("OP");var keys=new HashSet<>(expected);keys.addAll(Set.of("op","project","request"));if(q.get("op").equals("POLL")&&q.containsKey("editing")){keys.add("editing");if(!Set.of("true","false").contains(q.get("editing")))throw new IllegalArgumentException("FIELDS");}if(!keys.equals(q.keySet()))throw new IllegalArgumentException("FIELDS");if(Set.of("LIST","CREATE").contains(q.get("op"))){if(!q.get("project").isEmpty())throw new IllegalArgumentException("PROJECT");}else uuid(q.get("project"));}
 private Path directory(UUID project)throws IOException{return FirstLaunchFiles.safe(root.resolve(project.toString()));}
 private Room room(UUID id)throws IOException{Room r=rooms.get(id);if(r!=null)return r;if(rooms.size()>=32)throw new IOException("LIMIT");Path dir=directory(id);var meta=WorkspaceCodec122.decode(FirstLaunchFiles.read(dir.resolve("meta122"),4096),4096);if(!meta.keySet().equals(Set.of("project","owner","title"))||!id.toString().equals(meta.get("project")))throw new IOException("CORRUPT");UUID owner=uuid(meta.get("owner"));r=new Room(id,owner,meta.get("title"),new WorkspaceEngine121(dir.resolve("journal122"),id,owner));rooms.put(id,r);return r;}
 private List<UUID> projects()throws IOException{var ids=new ArrayList<UUID>();try(var stream=Files.list(root)){for(Path p:stream.toList())if(p.getFileName().toString().matches("[a-f0-9-]{36}")){FirstLaunchFiles.safe(p);if(Files.isRegularFile(p.resolve("meta122"),LinkOption.NOFOLLOW_LINKS)){ids.add(uuid(p.getFileName().toString()));if(ids.size()>32)throw new IOException("LIMIT");}}}ids.sort(Comparator.comparing(UUID::toString));return ids;}
 private WorkspacePolicy121 policy(Room r){return WorkspacePolicy121.restore(r.engine.policy());}
 private void member(Room r,UUID actor){if(!r.engine.policy().members().containsKey(actor))throw new SecurityException("DENIED");}
 private Map<String,String> view(Room r,UUID actor){member(r,actor);var out=new TreeMap<String,String>();out.put("result","OK");out.put("actor",actor.toString());out.put("store",WorkspaceRelease121.sha(key));out.put("project",r.id.toString());out.put("title",r.title);out.put("revision",Long.toString(r.engine.revision()));out.put("sync123","true");out.put("role",r.engine.policy().members().get(actor).role().name());var policy=policy(r);var rows=new StringBuilder();for(var f:new TreeMap<>(r.engine.files(actor)).values()){if(!policy.panel(actor,Panel.CODE,f.path()))continue;String kind;try{r.engine.document(actor,f.path());kind="TEXT";}catch(IllegalArgumentException e){kind="ASSET";}rows.append(f.path()).append('|').append(kind).append('|').append(WorkspaceRelease121.sha(f.bytes())).append('\n');}out.put("files",rows.toString());out.put("members",r.owner.equals(actor)?String.join("\n",r.engine.policy().members().entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->e.getKey()+"|"+e.getValue().role()).toList()):"");out.put("changes",String.join("\n",r.engine.changes(actor).stream().filter(c->policy.panel(actor,Panel.CODE,c.path())).map(c->c.path()+"|"+c.kind()).toList()));return out;}
 private void document(Room r,UUID actor,String path,Map<String,String> out)throws IOException{if(!policy(r).panel(actor,Panel.CODE,path))throw new SecurityException("DENIED");out.put("epoch",r.engine.epoch(actor,path).toString());out.put("path",path);out.put("document",WorkspaceCodec122.document(r.engine.document(actor,path)));out.put("editable",Boolean.toString(policy(r).allows(actor,Capability.EDIT,path)));out.put("peers",String.join("\n",r.presence.visible(policy(r),actor).stream().map(c->c.actor()+"|"+c.file()+"|"+c.label()+(c.editing()?" *":"")+"|"+c.rgb()+"|"+WorkspaceCodec122.id(c.anchor())+"|"+WorkspaceCodec122.id(c.selection())).toList()));}
 private void lease(Room r,UUID actor,String path,Map<String,String> out)throws IOException{if(!policy(r).allows(actor,Capability.EDIT,path))return;var range=r.engine.reserve(actor,path,2048);out.put("first",Long.toString(range.first()));out.put("last",Long.toString(range.last()));out.put("lease",Base64.getEncoder().encodeToString(LocalApply67.sign(key,Map.of("schema","122","project",r.id.toString(),"actor",actor.toString(),"path",path,"epoch",r.engine.epoch(actor,path).toString(),"first",Long.toString(range.first()),"last",Long.toString(range.last())))));}
 private void checkLease(Room r,UUID actor,String path,CollaborativeDocument121.Batch batch,String token)throws IOException{if(token.length()>4096)throw new IOException("LEASE");Map<String,String> d;try{d=LocalApply67.verify(key,Base64.getDecoder().decode(token));}catch(IllegalArgumentException e){throw new IOException("LEASE",e);}if(!d.keySet().equals(Set.of("schema","project","actor","path","epoch","first","last"))||!"122".equals(d.get("schema"))||!r.id.toString().equals(d.get("project"))||!actor.toString().equals(d.get("actor"))||!path.equals(d.get("path"))||!r.engine.epoch(actor,path).toString().equals(d.get("epoch")))throw new IOException("LEASE");long first=num(d.get("first")),last=num(d.get("last"));for(var i:batch.inserts())if(i.id().clock()<first||i.id().clock()>last)throw new IOException("LEASE");}
 public synchronized Map<String,String> execute(UUID actor,boolean mayCreate,String label,Map<String,String> q)throws IOException{
  if(closed)throw new IOException("CLOSED");request(q);String op=q.get("op");if(op.equals("LIST")){var lines=new ArrayList<String>();for(UUID id:projects()){var r=room(id);if(r.engine.policy().members().containsKey(actor))lines.add(id+"|"+r.title);}return Map.of("result","OK","actor",actor.toString(),"projects",String.join("\n",lines),"canCreate",Boolean.toString(mayCreate));}
  if(op.equals("CREATE")){if(!mayCreate)throw new SecurityException("DENIED");UUID id=uuid(q.get("request"));String title=q.get("text");if(title.isBlank()||title.length()>64||title.chars().anyMatch(c->Character.isISOControl(c)||c=='|'))throw new IllegalArgumentException("TITLE");Path dir=directory(id);if(!Files.exists(dir.resolve("meta122"))){if(projects().size()>=32)throw new IOException("LIMIT");Files.createDirectories(dir);try(var engine=new WorkspaceEngine121(dir.resolve("journal122"),id,actor)){}FirstLaunchFiles.write(dir.resolve("meta122"),WorkspaceCodec122.encode(Map.of("project",id.toString(),"owner",actor.toString(),"title",title),4096),false);}var r=room(id);if(!r.owner.equals(actor)||!r.title.equals(title))throw new SecurityException("REQUEST_REUSED");return view(r,actor);}
  var r=room(uuid(q.get("project")));member(r,actor);String path=q.getOrDefault("path","");Panel panel=switch(op){case "MEMBER"->Panel.MEMBERS;case "HISTORY","RESTORE"->Panel.HISTORY;case "PREVIEW","APPROVE"->Panel.RELEASES;case "EXPORT"->Panel.BUILD;default->Panel.CODE;};if(!Set.of("VIEW","LEAVE").contains(op)&&!(path.isEmpty()?policy(r).panel(actor,panel):policy(r).panel(actor,panel,path)))throw new SecurityException("DENIED");var out=new TreeMap<String,String>();
  switch(op){case "VIEW"->{}case "SYNC"->document(r,actor,path,out);case "OPEN","LEASE"->{policy(r).require(actor,Capability.READ,path);lease(r,actor,path,out);document(r,actor,path,out);}case "NEW"->{r.engine.createText(actor,num(q.get("rev")),path,"");lease(r,actor,path,out);document(r,actor,path,out);}case "EDIT"->{var batch=WorkspaceCodec122.batch(actor,q.get("batch"));checkLease(r,actor,path,batch,q.get("lease"));var next=new CollaborativeDocument121(r.engine.document(actor,path));next.apply(batch);if(next.text().codePointCount(0,next.text().length())>8192)throw new IOException("TEXT_LIMIT");WorkspaceCodec122.document(next.snapshot());r.engine.edit(actor,path,batch);document(r,actor,path,out);}case "POLL"->{UUID session=uuid(q.get("session"));if(!session.equals(r.sessions.put(actor,session)))r.presence.newSession(actor);var d=new CollaborativeDocument121(r.engine.document(actor,path));var a=WorkspaceCodec122.id(q.get("anchor"));var b=WorkspaceCodec122.id(q.get("selection"));d.position(a);d.position(b);r.presence.update(policy(r),actor,path,label,Integer.parseInt(q.get("color")),a,b,num(q.get("sequence")),Boolean.parseBoolean(q.getOrDefault("editing","false")));document(r,actor,path,out);}
   case "MEMBER"->{UUID target=uuid(q.get("target"));if(q.get("role").equals("NONE"))r.engine.revoke(actor,num(q.get("rev")),target);else{String prefix=q.get("prefix");var deny=enums(q.get("deny"),Capability.class);var hidden=enums(q.get("hidden"),Panel.class);r.engine.grant(actor,num(q.get("rev")),target,new Member(Role.valueOf(q.get("role")),prefix.isEmpty()?deny:Set.of(),prefix.isEmpty()?hidden:Set.of(),prefix.isEmpty()?List.of():List.of(new Rule(prefix,deny,hidden))));}}
   case "PREVIEW"->{var paths=new LinkedHashSet<>(List.of(q.get("paths").split("\n")));for(String p:paths)if(!policy(r).panel(actor,Panel.RELEASES,p))throw new SecurityException("DENIED");var s=r.engine.preview(actor,num(q.get("rev")),paths);for(String p:s.files().keySet())if(!policy(r).panel(actor,Panel.RELEASES,p))throw new SecurityException("DENIED");if(r.previews.size()>=16)r.previews.clear();r.previews.put(s.hash(),s);out.put("hash",s.hash());out.put("review",String.join("\n",s.files().values().stream().map(f->f.path()+"|"+WorkspaceRelease121.sha(f.bytes())).sorted().toList()));}
   case "APPROVE"->{var s=r.previews.get(q.get("hash"));if(s==null)throw new IllegalStateException("REVIEW_REQUIRED");for(String p:s.files().keySet())if(!policy(r).panel(actor,Panel.RELEASES,p))throw new SecurityException("DENIED");r.engine.approve(actor,num(q.get("rev")),s);out.put("hash",s.hash());}
   case "HISTORY"->out.put("history",String.join("\n",r.engine.history(actor,path).stream().map(e->e.revision()+"|"+e.actor()+"|"+e.action()).toList()));case "RESTORE"->r.engine.restore(actor,num(q.get("rev")),path,num(q.get("history")));case "RENAME"->r.engine.rename(actor,num(q.get("rev")),path,q.get("target"));case "DELETE_REVIEW"->out.put("ticket",r.engine.reviewDeletion(actor,num(q.get("rev")),path).toString());case "DELETE"->r.engine.deleteReviewed(actor,num(q.get("rev")),path,uuid(q.get("ticket")));case "LEAVE"->r.presence.newSession(actor);case "EXPORT"->out.put("export",export(r,actor));default->throw new IllegalArgumentException("OP");}
  out.putAll(view(r,actor));if(!path.isEmpty())out.put("path",path);return Map.copyOf(out);
 }
 private String export(Room r,UUID actor)throws IOException{var files=r.engine.build(actor);for(String p:files.keySet())if(p.equalsIgnoreCase("input122.manifest")||p.toLowerCase(Locale.ROOT).startsWith("input122.manifest/"))throw new IOException("EXPORT_RESERVED_PATH");for(String p:files.keySet())if(!policy(r).panel(actor,Panel.BUILD,p))throw new SecurityException("DENIED");String hash=r.engine.approvedHash(actor);Path exports=FirstLaunchFiles.safe(directory(r.id).resolve("exports"));Files.createDirectories(exports);Path target=FirstLaunchFiles.safe(exports.resolve(hash));byte[] manifest=WorkspaceCodec122.encode(Map.of("project",r.id.toString(),"hash",hash,"files",String.join("\n",files.values().stream().map(f->f.path()+"|"+WorkspaceRelease121.sha(f.bytes())).sorted().toList())),32700);if(!Files.exists(target)){Path temp=Files.createTempDirectory(exports,"building-");try{for(var f:files.values()){Path dest=FirstLaunchFiles.safe(temp.resolve(f.path()));Files.createDirectories(dest.getParent());FirstLaunchFiles.write(dest,f.bytes(),false);}FirstLaunchFiles.write(temp.resolve("input122.manifest"),manifest,false);Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE);}finally{if(Files.exists(temp))try(var walk=Files.walk(temp)){for(Path p:walk.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}}for(var f:files.values())if(!Arrays.equals(f.bytes(),FirstLaunchFiles.read(target.resolve(f.path()),8*1024*1024)))throw new IOException("EXPORT_CHANGED");if(!Arrays.equals(manifest,FirstLaunchFiles.read(target.resolve("input122.manifest"),32700)))throw new IOException("EXPORT_CHANGED");try(var walk=Files.walk(target)){int count=0;for(Path p:walk.toList()){FirstLaunchFiles.safe(p);if(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)){String rel=target.relativize(p).toString().replace('\\','/');if(!rel.equals("input122.manifest")&&!files.containsKey(rel)||++count>513)throw new IOException("EXPORT_CHANGED");}}}return hash;}
 public synchronized void checkImport(UUID actor,UUID project)throws IOException{Path dir=directory(project),marker=dir.resolve("migration122");if(Files.exists(marker)){var d=WorkspaceCodec122.decode(FirstLaunchFiles.read(marker,32700),32700);if(!actor.toString().equals(d.get("owner"))||!project.toString().equals(d.get("project")))throw new SecurityException("DENIED");}else if(Files.exists(dir.resolve("journal122"))||Files.exists(dir.resolve("meta122")))throw new IOException("EXISTS_OR_LIMIT");}
 public synchronized Map<String,String> importLegacy(UUID actor,com.fixmer.genesis.technology.workspace.WorkspaceStore112.Export122 source)throws IOException{
  if(closed||!actor.equals(source.owner()))throw new SecurityException("DENIED");UUID id=source.project();checkImport(actor,id);Path dir=directory(id);var manifest=new TreeMap<String,String>();manifest.put("owner",actor.toString());manifest.put("project",id.toString());manifest.put("title",source.title());manifest.put("revision",Long.toString(source.revision()));manifest.put("members",String.join("\n",source.members().entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->e.getKey()+"|"+e.getValue()).toList()));manifest.put("files",String.join("\n",source.files().entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->e.getKey()+"|"+WorkspaceRelease121.sha(e.getValue().getBytes(StandardCharsets.UTF_8))).toList()));byte[] seal=WorkspaceCodec122.encode(manifest,32700);Path marker=dir.resolve("migration122");Files.createDirectories(dir);if(Files.exists(marker)){if(!Arrays.equals(FirstLaunchFiles.read(marker,32700),seal))throw new IOException("MIGRATION_CHANGED");}else FirstLaunchFiles.write(marker,seal,false);if(Files.exists(dir.resolve("meta122")))return view(room(id),actor);
  try(var engine=new WorkspaceEngine121(dir.resolve("journal122"),id,actor)){var existing=engine.files(actor);for(var e:existing.entrySet())if(!source.files().containsKey(e.getKey())||!Arrays.equals(e.getValue().bytes(),source.files().get(e.getKey()).getBytes(StandardCharsets.UTF_8)))throw new IOException("MIGRATION_CHANGED");for(var e:source.files().entrySet())if(!existing.containsKey(e.getKey()))engine.createText(actor,engine.revision(),e.getKey(),e.getValue());for(var e:source.members().entrySet())if(!e.getKey().equals(actor)){Role role=switch(e.getValue()){case OWNER->throw new IOException("OWNER");case MANAGER->Role.MAINTAINER;case EDITOR->Role.DEVELOPER;case VIEWER->Role.VIEWER;};var member=new Member(role,Set.of(),Set.of(),List.of());var prior=engine.policy().members().get(e.getKey());if(prior!=null&&!prior.equals(member))throw new IOException("MIGRATION_CHANGED");if(prior==null)engine.grant(actor,engine.revision(),e.getKey(),member);}}FirstLaunchFiles.write(dir.resolve("meta122"),WorkspaceCodec122.encode(Map.of("project",id.toString(),"owner",actor.toString(),"title",source.title()),4096),false);return view(room(id),actor);
 }
 private static <T extends Enum<T>> Set<T> enums(String s,Class<T> type){var out=EnumSet.noneOf(type);if(!s.isEmpty())for(String part:s.split(","))if(!out.add(Enum.valueOf(type,part)))throw new IllegalArgumentException("ENUM");return out;}
 @Override public synchronized void close()throws IOException{closed=true;IOException failure=null;for(var r:rooms.values())try{r.engine.close();}catch(IOException e){failure=e;}rooms.clear();if(failure!=null)throw failure;}
}
